// Lucca: access to the ported Webflow markup of every page except the homepage (src/webflow/, generated by
// client-docs/webflow/tools/port-lucca.mjs). Each fragment is the live page's .main-wrapper content; the
// header/footer come from Header.astro/Footer.astro (Armando's homepage rebuild), so they match on every page.
import type { SiteInfo } from "../data/site";
import { withTrackingPhone } from "./utils/phone";
import pagesJson from "../webflow/pages.json";

export interface WebflowPageMeta {
  file?: string;
  title: string;
  description: string;
  ogTitle?: string;
  ogDescription?: string;
  ogImage?: string;
  pageId: string;
  /** Webflow's per-page <style> (IX2 initial states for breakpoints). */
  headStyles?: string;
  /** The page's own inline <script> (ebook pages: the form opens the Google Drive download). */
  bodyScript?: string;
}

const fragments = import.meta.glob("../webflow/pages/*.html", { query: "?raw", import: "default", eager: true }) as Record<string, string>;

export const webflowPages = pagesJson as unknown as Record<string, WebflowPageMeta>;

/** Routes rendered by pages/[...wf].astro (the blog index has its own page). */
export function staticWebflowRoutes(): string[] {
  return Object.keys(webflowPages).filter((r) => r.startsWith("/") && r !== "/blog");
}

export function getWebflowPage(route: string) {
  const meta = webflowPages[route];
  if (!meta?.file) throw new Error(`No ported Webflow page for ${route}`);
  return { meta, html: fragments[`../webflow/pages/${meta.file}`] };
}

/** Under a GitHub Pages preview (astro.config.mjs PAGES_BASE) root paths need the base; the post-build
 *  step already prefixes hand-written root paths in the HTML, so nothing to do here. */
export function prepare(html: string, site: SiteInfo): string {
  return withTrackingPhone(html, site);
}
